import fs from 'node:fs';
import assert from 'node:assert/strict';
export const entry=JSON.parse(fs.readFileSync(new URL('fixtures/question-bank-batch2b-round2-before-20261104.json',import.meta.url),'utf8'));
export const version='question-authoring.2026-11-04.batch2b.round2.v1';
export const p=s=>'{patientName}, a {ageYears}-year-old {sexNoun}, '+s;
export const table=(caption,columns,rows,cells)=>({kind:'table',caption,columnHeaders:columns,rowHeaders:rows,cells});
export const none={kind:'no_test'},test=name=>({kind:'test',timingProfileId:'timing.test.'+name});
export const construct=(id,name,objective,reason)=>({id:'concept.'+id,name,objective,reason});
export const specs=[];
export function add(id,s){
 const prior=id==='F13'?entry.f13:entry.packet.find(x=>x.id===id);assert(prior,id);
 const cs=entry.release.cases.find(c=>c.id===prior.caseId),node=cs.decisionNodes.find(n=>n.id===prior.nodeId);
 const question=entry.questions[node.questionVariantId]?.find(q=>q.answerChoices?.length);assert(question,id);
 assert(!entry.review.find(r=>r.id===id&&r.verdict==='PASS'));
 specs.push({id,prior,cs,node,question,claims:prior.supportingEvidenceClaimIds??question.supportingEvidenceClaimIds,...s});
}

