 construct:construct('nutrition.delivered-intake-before-route-escalation.v1','Reconcile intake delivery with inflammatory albumin change','Compare actual consumed nutrition with the current assessed targets before adding a feeding route because a laboratory marker deteriorates.','Changes obvious decline-to-support matching into a delivery/laboratory conflict; retain the prior nutritional-risk assessment card.'),
 numericCheck:{kind:'intake',energy:[1200,600],protein:[50,25],targetEnergy:1800,targetProtein:75},
